import torch
from torch import nn
width = 4  # shared configuration
class Model(nn.Module):
    def __init__(self):
        super().__init__()
        self.first = nn.Linear(in_features=width, out_features=4, bias=False)  # preserve constructor and comment
        self.shared = self.first
        self.last = nn.Linear(width, 2)
    def forward(self, h):
        a = self.first(h)
        b = self.shared(h)
        return self.last(a + b)

